import { copyTextToClipboard, DefaultHtmlParserService, getTextFromClipboard } from "@node-projects/web-component-designer";
export class MermaidLayoutCopyPasteService {
    async copyItems(designItems) {
        let savedata = "";
        for (const designItem of designItems) {
            savedata += designItem.element.outerHTML;
        }
        await copyTextToClipboard(savedata);
    }
    async getPasteItems(serviceContainer, instanceServiceContainer) {
        const text = await getTextFromClipboard();
        const htmlParser = new DefaultHtmlParserService();
        const result = await htmlParser.parse(text, serviceContainer, instanceServiceContainer, true);
        return [result, null];
    }
}
